import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"兌為澤","description":"周易折中 - 兌為澤","frontmatter":{"title":"兌為澤","description":"周易折中 - 兌為澤"},"headers":[],"relativePath":"classics/zhezhong/064.md","filePath":"classics/zhezhong/064.md"}'),h={name:"classics/zhezhong/064.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="兌為澤" tabindex="-1">兌為澤 <a class="header-anchor" href="#兌為澤" aria-label="Permalink to “兌為澤”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈兌序卦〉：“《巽》者，入也。入而後說之，故受之以《兌》。《兌》者，說也。物相入則相說，相說則相入。《兌》所以次《巽》也。”</p><p>兌：亨，利貞</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>兌，說也。一陰進乎二陽之上，喜之見乎外也。其象為澤，取其說萬物，又取坎水而塞其下流之象。卦體剛中而柔外，剛中故說而亨，柔外故利於貞。蓋說有亨道，而其妄說不可以不戒，故其佔如此。又柔外故為說亨，剛中故利於貞，亦一義也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>兌，說也。說致亨之道也。能說於物，物莫不說而與之，足以致亨。然為說之道，利於貞正。非道求說，則為邪諂而有悔咎，故戒利貞也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>焦氏竑曰 ：人有喜說，必見而在外。蓋陽假陰之和柔以為用，喜說非由於陰也。故二陰一陽則陽為之主，二陽一陰則陰非為主，但為陽之用耳。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>地有積溼，春氣至則潤升於上；人身有血，陽氣盛則腴敷於色。此兌為澤、為說之義。蓋說雖緣陰，而所以用陰者陽也。人有柔和之質，而非以忠直之心行之，則失正而入於邪矣。故利貞。</p><p>象曰：麗澤兌，君子以朋友講習</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>兩澤相麗，互相滋益，朋友講習，其象如此。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>麗澤，二澤相附麗也。兩澤相麗，交相浸潤，互有滋益之象，故君子觀其象而以朋友講習。朋友講習，互相益也。先儒謂天下之可說莫若朋友講習，朋友講習固可說之大者，然當明相益之象。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰 ：學以聚之，問以辨之。兌兩口對，故朋友講習也。</p></li><li><p>孔氏穎達曰 ：同門曰朋，同志曰友。朋友聚居，講習道義，相說之盛，莫過於此也。</p></li><li><p>程子曰 ：天下之說不可極，惟朋友講習，雖過說無害。兌澤有相滋益處。</p></li><li><p>蘇氏軾曰 ：取其樂而不流者也。</p></li><li><p>朱氏震曰 ：講其所知，習其所行。</p></li><li><p>蔡氏淵曰 ：講兌象，習重兌象。</p></li><li><p>俞氏琰曰 ：講者講其所未明，講多則義理明矣；習者習其所未熟，習久則踐履熟矣。此朋友講習所以為有滋益而如兩澤之相麗也。若獨學無友，則孤陋而寡聞。故《論語》以學之不講為憂，以學而時習為說，以有朋自遠方來為樂。</p></li></ul><p>彖曰：兌，說也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名義</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>張氏雨若曰：此釋名義類《鹹》，兌者無言之說，以說解兌，兌木為說，特以其說不在言而稱兌耳。</li></ul><p>剛中而柔外，說以利貞，是以順乎天而應乎人，說以先民，民忘其勞；說以犯難，民忘其死。說之大，民勸矣哉！</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦辭而極言之。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>兌之義說也。一陰居二陽之上，陰說於陽而為陽所說也。陽剛居中，中心誠實之象；柔爻在外，接物和柔之象，故為說而能貞也。利貞，說之道宜正也。卦有剛中之徳，能貞者也。說而能貞，是以上順天理，下應人心，說道之至正至善者也。若夫違道以幹百姓之譽者，苟說之道，違道不順，天干譽非應人，苟取一時之說耳，非君子之正道。君子之道，其說於民，如天地之施，感於其心而說服無斁，故以之先民，則民心說隨而忘其勞；率之以犯難，則民心說服於義而不恤其死。說道之大，民莫不知勸。勸，謂信之而勉力順從。人君之道，以人心說服為本，故聖人贊其大。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：說而違剛則諂，剛而違說則暴。剛中而柔外，所以說以利貞也。剛中故利貞，柔外故說亨。</p></li><li><p>劉氏牧曰：天之所助者順也，人之所助者信也。柔外為順，剛中為信，故得順乎天而應乎人。</p></li><li><p>呂氏祖謙曰：當適意時而說，與處安平時而說，皆未足為難。惟當勞苦患難而說，始見真說。聖人以此先之，故能使之任勞苦而不辭，赴患難而不畏也。</p></li></ul><p>初九：和兌，吉</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>以陽爻居說體而處最下，又無系應，故其象佔如此。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>初雖陽爻居說體，而在最下，無所繫應，是能卑下和順以為說，而無所偏私者也。以和為說而無所偏私，說之正也。陽剛則不卑，居下則能巽，處說則能和，無應則不偏。處說如是，所以吉也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蔡氏淵曰 ：爻位皆剛，不比於柔，得說之正，和而不流者也，故吉。</p></li><li><p>吳氏澄曰 ：六畫唯初不比陰柔，說道之善，故曰“和”。</p></li><li><p>趙氏玉泉曰 ：陽剛則無邪媚之嫌，居下則無上求之念，無應又無私系之累。其說也不諂不凟，中節而無乖戾，和兌之象如是，則說得其正矣。</p></li><li><p>來氏知德曰 ：“和”，與《中庸》“發而皆中節謂之和”同。謂其所說者無乖戾之私，皆性情之正，道義之公也。</p></li></ul><p>象曰：和兌之吉，行未疑也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>居卦之初，其說也正，未有所疑也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>有求而和，則涉於邪諂。初隨時順處，心無所繫，無所為也，以和而已，是以吉也。象又以其處說在下而非中正，故云行未疑也。其行末有可疑，謂未見其有失也。若得中正則無是言也，說以中正為本，爻直陳其義，象則推而盡之。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蔡氏淵曰 ：初未牽於陰，所行未有疑惑。若四比三，有商兌之疑矣。</p></li><li><p>徐氏幾曰 ：疑謂繫於陰也。卦四陽，惟初與陰無系，故未疑。</p></li><li><p>鄭氏維嶽曰 ：以陽剛居兌初，又不與陰比，故信心信理而出行之於外者，未與心疑。使有系應，便不能自決矣。</p></li></ul><p>九二：孚兌，吉，悔亡</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>剛中為孚，居陰為悔。佔者以孚而說，則吉而悔亡矣。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>二承比陰柔，陰柔小人也。說之則當有悔。二剛中之德，孚信內充，雖比小人，自守不失，君子和而不同，說而不失剛中，故吉而悔亡。非二之剛中，則有悔矣，以自守而亡也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰 ：六三陰柔而不正，所謂非道以說者也。而二比之，疑於有悔矣。然二以剛居中，誠實之德充足於內，故雖與三同體而無失己之嫌，此其悔所以亡也。</p></li><li><p>龔氏煥曰 ：九二陽剛得中，當說之時，以孚信為說者也。已以孚信為說，人不得而妄說之，所以吉也。</p></li></ul><p>象曰：孚兌之吉，信志也</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>心之所存為志，二剛實居中，孚信存於中也。志存誠信，豈至說小人而自失乎？是以吉也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>何氏楷曰 ：初去三遠，不特志可信，而行亦未涉於可疑。二去三近，行雖不免於可疑，而志則可信。</li></ul><p>六三：來兌，兇</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>陰柔不中正，為兌之主，上無所應而反來就二陽以求說，兇之道也。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>六三陰柔不中正之人，說不以道者也。來兌，就之以求說也。比於在下之陽，枉己非道就以求說，所以兇也。之內為來，上下俱陽而獨之內者，以同體而陰性下也，失道下行也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏宗傳曰 ：六三居兩兌之閒，一兌既盡，一兌復來，故曰“來兌”。夫以不正之才，居兩兌之閒，左右逢迎，惟以容說為事，此小人之失正者，故於兌為兇。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>三居內體，故曰“來”。然非來說於下二陽之謂也，為說之主，志在於說，凡外物之可說者皆感之而來也。</p><p>象曰：來兌之兇，位不當也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>自處不中正，無與而妄求說，所以兇也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>熊氏良輔曰 ：六三位不當，居上下二兌之閒。下兌方終，上兌又來，說而又說，不得其正者也。上六曰“引兌”，蓋與六三相表裡。</li></ul><p>九四：商兌，未寧，介疾有喜</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>四上承九五之中正，而下比六三之柔邪，故不能決而商度所說，未能有定然。質本陽剛，故能介然守正而疾惡柔邪，也如此則有喜矣。象佔如此，為戒深矣。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>四上承中正之五，而下比柔邪之三。雖剛陽而處非正，三陰柔，陽所說也，故不能決而商度未寧，謂擬議所從而未決，未能有定也。兩間謂之介，分限也（地之界則加田，義乃同也），故人有節守謂之介。若介然守正而疾遠邪惡，則有喜也。從五正也，說三邪也。四近君之位，若剛介守正，疾遠邪惡，將得君以行道，福慶及物，為有喜也。若四者得失未有定，系所從耳。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏簡曰 ：九剛四柔，近比六三諛佞之小人，心知其非而實樂其柔媚，故商度所說去耶交戰於胸中而未寧。聖人於是勉之曰：介然疾惡小人，則有喜。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>易中“疾”字皆與“喜”對，故曰“無妄之疾，勿藥有喜”，又曰“損其疾，使遄有喜”。以此爻例之，則“疾”者謂疾病也，“喜”者謂病去也。四比於三，故曰“介疾”，言介於邪害之閒也。若安而溺焉，則其為鴆毒大矣。惟能商度所說而不以可說者為安，則雖介疾而有喜矣。《論語》曰：“君子易事而難說也，說之不以道，不說也。”其“商兌”之謂乎。</p><p>象曰：九四之喜，有慶也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>所謂喜者，若守正而君說之，則得行其陽剛之道，而福慶及物也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>郭氏雍曰 ：當兌之時，虞上下之際，不妄從說，知所擇者也。介然自守，故能全兌說之喜。喜非獨一身而已，終亦有及物之慶也。</li></ul><p>九五：孚於剝，有厲</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>剝謂陰能剝陽者也。九五陽剛中正，然當說之時而居尊位，宻近上六。上六陰柔，為說之主，處說之極，能妄說以剝陽者也。故其佔但戒以信於上六，則有危也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>九五得尊位而處中正，盡說道之善矣。而聖人復設有厲之戒，蓋堯舜之盛，未嘗無戒也，戒所當戒而已。雖聖賢在上，天下未嘗無小人，然不敢肆其惡也。聖人亦說其能勉而革面也。彼小人者，未嘗不知聖賢之可說也，如四凶處堯朝，隱惡而順命是也。聖人非不知其終惡也，取其畏罪而強仁耳。五若誠心信小人之假善為實善，而不知其色藏，則危道也。小人者，備之不至則害於善。聖人為戒之意深矣。剝者，消陽之名，陰消陽者也，蓋指上六。故孚於剝則危也。以五在說之時而宻比於上六，故為之戒。雖舜之聖，且畏巧言令色，安得不戒也？說之惑人易入而可懼也如此。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：比於上六而與相得，處尊正之位，不說信乎陽而說信乎陰，孚於剝之義也。剝之為義，小人道長之謂。</p></li><li><p>楊氏簡曰 ：九五親信上六柔媚不正之小人，故曰“孚於剝”。剝之為卦，小人剝君子，又剝喪其國家，故謂小人為剝。信小人，危厲之道也。</p></li><li><p>胡氏炳文曰 ：說之感人最為可懼，感之者將以剝之也。況為君者易狃於所說，故雖聖人且畏巧言令色，況凡為君子者乎？</p></li><li><p>錢氏一本曰 ：兌五說體與履五健體不同，履五健，恐其和之難，危在夬；兌五說，不覺其入之易，危在孚。故皆有厲之象。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>易中凡言“厲”者，皆兼內外而言，蓋事可危而吾危之也。履五爻及此爻，皆以剛中正居尊位而有厲辭。夫子又皆以位正當釋之，是其危也。以剛中正，故能危也。履卦有危懼之義，而九五居尊，所謂“履帝位而不疚”者，故能因夬履而常危；兌有說義，九五居尊，又比上六，故亦因孚於剝而心有危也。此有厲與夬有厲正同，皆以九五比近上六，所謂其危乃光者也。</p><p>象曰：孚於剝，位正當也</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>與履九五同。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>戒孚於剝者，以五所處之位正當戒也。密比陰柔，有相說之道，故戒在信之也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰 ：謂正當尊位，若孚上之柔說，則消剝於陽必矣。</li></ul><p>上六：引兌</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>上六成說之主，以陰居說之極，引下二陽相與為說，而不能必其從也。故九五當戒，而此爻不言其吉凶。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>他卦至極則變，兌為說極則愈說。上六成說之主，居說之極，說不知已者也。故說既極矣，又引而長之。然而不至悔咎，何也？曰方言其說，不知已，未見其所說善惡也。又下乘九五之中正，無所施其邪說。六三則承乘皆非正，是以有兇。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>劉氏牧曰 ：執德不固，見誘則從，故稱“引兌”。</p></li><li><p>毛氏璞曰 ：所以為兌者，三與上也。三為內卦，故曰“來”；上為外卦，故曰“引”。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>三與上皆以陰柔為說主。來兌者，物感我而來，孟子所謂“蔽於物”，樂記所謂“感於物而動”者也。引兌者，物引我而去，孟子所謂“物交物則引之而已矣”，樂記所謂“物至而人化物”者也。始於來，終於引，此人心動乎欲之淺深也。</p><p>象曰：上六引兌，未光也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>說既極矣，又引而長之，雖說之之心不已，而事理已過，實無所說。事之盛則有光輝，既極而強引之長，其無意味甚矣，豈有光也？“未”非必之辭，象中多用“非必”，能有光輝謂不能光也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏啟新曰 ：來兌、引兌皆小人也。在君子，則當來而勿受，引而勿去也。君子以道德相引，其道為光明。引而為說，則心術曖昩，行事邪僻，甚矣，豈得為光乎？</li></ul><p>總論</p><ul><li><p>龔氏煥曰 ：兌本以說之見乎外而得名，然六爻之義皆不取說之徇乎外者。人之所說苟能不徇乎外，則其見於外者斯得其正而吉矣。</p></li><li><p>蔣氏悌生曰 ：當說之時，剛則有節，柔則無度。故此卦初二及四五四爻皆以剛陽而得吉，三上二爻皆以陰柔而致兇。</p></li></ul>',117)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
